mapper.select:
SELECT *
FROM recipe_change_notice
WHERE notify_id = #{notifyId}
  AND workshop_code = #{workshopCode}
  AND deleted = 0

mapper.update:
UPDATE recipe_change_notice
SET status       = #{toStatus},
    mq_send_time = CURRENT_TIMESTAMP,
    error_msg    = NULL,
    update_time  = CURRENT_TIMESTAMP,
    updater      = #{updater}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE recipe_change_notice
SET mq_send_time = CURRENT_TIMESTAMP,
    updater      = #{updater}
WHERE id = #{id}

UPDATE recipe_change_notice
SET status = #{toStatus},
error_msg = #{errorMsg},
update_time = CURRENT_TIMESTAMP,
updater = #{updater}
WHERE id = #{id}
AND status = #{fromStatus}

UPDATE recipe_change_notice
SET status      = #{dispatchingStatus},
    error_msg   = NULL,
    update_time = CURRENT_TIMESTAMP,
    updater     = #{updater}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE recipe_change_notice
SET update_time = CURRENT_TIMESTAMP,
    updater     = #{updater}
WHERE id = #{id}
  AND status = #{dispatchingStatus}
  AND update_time <= CURRENT_TIMESTAMP - INTERVAL '1 minute'

UPDATE recipe_change_notice
SET retry_count = retry_count + 1
WHERE id = #{id}
  AND status = #{dispatchingStatus}

UPDATE recipe_change_notice
SET status      = #{toStatus},
    update_time = CURRENT_TIMESTAMP,
    updater     = #{updater}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE recipe_change_notice
SET status = #{toStatus},
    update_time = CURRENT_TIMESTAMP,
    updater = #{updater}
WHERE id = #{id}
  AND status = #{fromStatus}

UPDATE recipe_change_notice
SET status                 = #{processingStatus},
    processing_token       = #{processingToken},
    processing_lease_until = CURRENT_TIMESTAMP + (#{processingLeaseMillis} * INTERVAL '1 millisecond'),
    error_msg              = NULL,
    update_time            = CURRENT_TIMESTAMP,
    updater                = #{updater}
WHERE id = #{id}
  AND (

      status = #{dispatchingStatus}

      OR status = #{sentStatus}

      OR status = #{mesProcessFailedStatus}

      OR (status = #{processingStatus}
          AND (processing_lease_until IS NULL OR processing_lease_until <= CURRENT_TIMESTAMP))
  )

UPDATE recipe_change_notice
SET status                 = #{toStatus},
    error_msg              = #{errorMsg},
    processing_token       = NULL,
    processing_lease_until = NULL,
    update_time            = CURRENT_TIMESTAMP,
    updater                = #{updater}
WHERE id = #{id}
  AND status = #{fromStatus}
  AND processing_token = #{processingToken}

mapper.select:
SELECT id, notify_id, workshop_code, status, retry_count, max_retry, create_time
FROM recipe_change_notice
WHERE deleted = 0

    AND notify_id = #{pageReqVO.notifyId}


    AND workshop_code = #{pageReqVO.workshopCode}


    AND status = #{pageReqVO.status}


    AND create_time  >=  #{pageReqVO.createTime[0]}
    AND create_time  <=  #{pageReqVO.createTime[1]}

ORDER BY create_time DESC, id DESC

